import { useMemo, useState } from 'react';
import { Button, Calendar, Card, Stack, Text } from '@jinx-ui/react';

export type ReportDatePickerProps = {
  defaultValue?: Date;
  onChange: (date: Date) => void;
};

const startOfDay = (date: Date) =>
  new Date(date.getFullYear(), date.getMonth(), date.getDate());

const daysAgo = (days: number) => {
  const date = startOfDay(new Date());
  date.setDate(date.getDate() - days);
  return date;
};

const isSameDay = (a: Date, b: Date) => a.getTime() === b.getTime();

export default function ReportDatePicker({ defaultValue, onChange }: ReportDatePickerProps) {
  const [value, setValue] = useState<Date>(() => startOfDay(defaultValue ?? new Date()));

  const presets = useMemo(
    () => [
      { id: 'today', label: 'Сегодня', days: 0 },
      { id: 'yesterday', label: 'Вчера', days: 1 },
      { id: 'week', label: 'Неделя назад', days: 7 },
    ],
    [],
  );

  const select = (next: Date) => {
    const day = startOfDay(next);
    setValue(day);
    onChange(day);
  };

  return (
    <Card>
      <Stack direction="column" gap="md">
        <Text as="label" id="report-date-label" size="sm" tone="muted">
          Дата отчёта
        </Text>

        <Stack direction="row" gap="sm" wrap>
          {presets.map((preset) => {
            const presetDate = daysAgo(preset.days);
            const active = isSameDay(presetDate, value);

            return (
              <Button
                key={preset.id}
                type="button"
                size="sm"
                variant={active ? 'primary' : 'ghost'}
                aria-pressed={active}
                onClick={() => select(presetDate)}
              >
                {preset.label}
              </Button>
            );
          })}
        </Stack>

        <Calendar
          aria-labelledby="report-date-label"
          value={value}
          defaultMonth={value}
          onChange={select}
        />
      </Stack>
    </Card>
  );
}

